INSERT INTO "survey" ("title", "id") VALUES
('Как я веду себя',	1);
INSERT INTO "game" ("id", "title", "t_voice", "description", "game_group_id", "duration", "cover_image", "music") VALUES
(1,	'Слово сильнее',	'/content/games/game_1/title_game.mp3',	'Живое и интригующее — сразу говорит о конфликте и внутреннем напряжении. Ребёнок захочет узнать, что будет дальше',	1,	3,	'/content/cover_1.png',	'/content/background.mp3'),
(2,	'Решай с умом',	'/content/games/game_2/title_game.mp3',	'Немного дерзкое и разговорное. Подходит для подросткового мышления: ты можешь быть крутым, даже не залезая.',	2,	3,	'/content/cover_2.png',	'/content/background.mp3'),
(3,	'Не бойся быть другим',	'/content/games/game_3/title_game.mp3',	'Интерактивное приключение с загадками и моральными выборами. Азоту предстоит сделать правильный',	3,	3,	'/content/cover_3.png',	'/content/background.mp3'),
(4,	'Секрет, которого не должно быть',	'/content/games/game_4/title_game.mp3',	'Звучит интригующе, эмоционально. Внутренний голос — главный герой.',	4,	3,	'/content/cover_4.png',	'/content/background.mp3'),
(5,	'Выключаю чат',	'/content/games/game_5/title_game.mp3',	'Прямо по сути. Дети это поймут, а взрослые — одобрят',	5,	3,	'/content/cover_5.png',	'/content/background.mp3');
INSERT INTO "question" ("text", "group_id", "voice", "id", "survey_id") VALUES
('Я легко теряю терпение',	1,	'/content/Survey/Q1.mp3',	1,	1),
('Если меня обидели, то я обязательно отомщу',	1,	'/content/Survey/Q2.mp3',	2,	1),
('Часто я злю других специально',	1,	'/content/Survey/Q3.mp3',	3,	1),
('Я очень редко ссорюсь с родными',	1,	'/content/Survey/Q4.mp3',	4,	1),
('Я не люблю, когда мне делают замечания',	1,	'/content/Survey/Q5.mp3',	5,	1),
('Мне нравится делать что-то опасное',	2,	'/content/Survey/Q6.mp3',	6,	1),
('Я люблю испытывать страх',	2,	'/content/Survey/Q7.mp3',	7,	1),
('Если кого-то обижают, то я не вмешиваюсь',	2,	'/content/Survey/Q8.mp3',	8,	1),
('Я иногда нарушаю установленные взрослыми правила',	2,	'/content/Survey/Q9.mp3',	9,	1),
('Я люблю острые ощущения',	2,	'/content/Survey/Q10.mp3',	10,	1),
('Я жду помощи от взрослых',	3,	'/content/Survey/Q11.mp3',	11,	1),
('Я не могу отказать, когда меня о чем-то просят',	3,	'/content/Survey/Q12.mp3',	12,	1),
('Я не общаюсь со сверстниками, так как они меня обижают',	3,	'/content/Survey/Q13.mp3',	13,	1),
('Мне трудно просить других о помощи',	3,	'/content/Survey/Q14.mp3',	14,	1),
('Мне часто кажется, что я не справлюсь',	3,	'/content/Survey/Q15.mp3',	15,	1),
('Верю всему, что говорят по радио и телевидению',	4,	'/content/Survey/Q16.mp3',	16,	1),
('Я доверяю незнакомым людям',	4,	'/content/Survey/Q17.mp3',	17,	1),
('Иногда я делаю не думая',	4,	'/content/Survey/Q18.mp3',	18,	1),
('Другие люди кажутся счастливее меня',	4,	'/content/Survey/Q19.mp3',	19,	1),
('Я всегда соглашаюсь с окружающими',	4,	'/content/Survey/Q20.mp3',	20,	1),
('Меня часто обижают',	5,	'/content/Survey/Q21.mp3',	21,	1),
('Я часто попадаю в беду',	5,	'/content/Survey/Q22.mp3',	22,	1),
('Я часто чувствую, что все против меня',	5,	'/content/Survey/Q23.mp3',	23,	1),
('Меня часто дразнят',	5,	'/content/Survey/Q24.mp3',	24,	1),
('Я не умею защищаться',	5,	'/content/Survey/Q25.mp3',	25,	1),
('Я никогда никого не обижал',	6,	'/content/Survey/Q26.mp3',	26,	1),
('Я всегда слушаюсь взрослых',	6,	'/content/Survey/Q27.mp3',	27,	1),
('У меня не бывает плохого настроения',	6,	'/content/Survey/Q28.mp3',	28,	1),
('Я всегда говорю правду',	6,	'/content/Survey/Q29.mp3',	29,	1),
('Я никогда не злюсь',	6,	'/content/Survey/Q30.mp3',	30,	1);
